export interface Character {
  id: string;
  name: string;
  universe: string;
  category: 'Anime' | 'Cartoon' | 'WWE' | 'AEW' | 'Toku' | 'Video Games';
  imageUrl: string;
  /** Optional high-quality portrait (e.g. /portraits/<id>.png). Falls back to imageUrl. */
  portraitUrl?: string;
  powers: string[];
  finisher: string;
  finisherColor: string;
  finisherType: string;
  finisherType2: string;
  finisherType3: string;
  finisherType4: string;
  kissDrain?: boolean;
  kissName?: string;
  kissPoison?: boolean;
  finisher2: string;
  finisher3: string;
  finisher4: string;
}

/** Resolve the best image for a character: portraitUrl when set, else imageUrl. */
export function getPortraitUrl(char: { portraitUrl?: string; imageUrl: string }): string {
  return char.portraitUrl || char.imageUrl;
}

